_ARTWORK_LINES = _ARTWORK.splitlines()
_ARTWORK_WIDTH = utils.visible_width(_ARTWORK_LINES[0])  # every captured row is the same width


def get_artwork_string() -> str:
    """
    Right-aligns the artwork against the current terminal width, recomputed on every call so a
    mid-page resize (see curses_ui.prompt_page's background() callback) re-aligns it rather than
    freezing it to whatever the width was on the page's first draw -- same approach as
    render_splash.get_splash_string().
    """
    if not sys.stdout.isatty():
        return utils.strip_ansi(_ARTWORK)

    pad = " " * max(0, utils.terminal_width() - _ARTWORK_WIDTH)
    return "\n".join(pad + line for line in _ARTWORK_LINES)
